let previousId={};
export function generateFormalReading(category='policy',length=1,framework='prep',theme='life'){
  if(!READING_CATEGORIES[category])category='policy';
  length=[1,2,3].includes(Number(length))?Number(length):1;
  const bank=FORMAL_READINGS.filter(r=>category==='all'||r.category===category);
  let index=Math.floor(Math.random()*bank.length);
  if(bank[index].id===previousId[category])index=(index+1)%bank.length;
  previousId[category]=bank[index].id;
  const chosen=Array.from({length},(_,i)=>bank[(index+i)%bank.length]);
  const sections=chosen.map(r=>({id:r.id,title:r.title,text:r.blocks.join('\n\n'),kind:r.kind,source:{...r.source}}));
  return {id:crypto.randomUUID(),mode:'reading',theme,length,framework,readingCategory:category,seed:index,
    title:sections.length===1?sections[0].title:`${READING_CATEGORIES[category]}联读 · ${sections.length}篇`,
    sourceLabel:sections.length===1?sections[0].kind:'分篇标注原创练习稿',sections,
    text:sections.map(s=>s.text).join('\n\n'),practiceHint:chosen[0].hint};
}
